// composable: reusable behavior, no global state
export function useCartTotals(items: Ref<CartItem[]>) {
  const total = computed(() => items.value.reduce((s, i) => s + i.priceCents, 0))
  return { total }
}

// store: shared state with an owner and a lifecycle
export const useCartStore = defineStore("cart", {
  state: () => ({ items: [] as CartItem[] }),
  actions: { add(item: CartItem) { this.items.push(item) } }
})
